// arrivalRate in requests/second, holdTime in seconds
function report(label, arrivalRate, holdTime) {
  const inFlight = Math.round(arrivalRate * holdTime);
  const survives = inFlight <= 200;
  console.log(label + ': ' + inFlight + ' threads, survives=' + survives);
}

report('slow-no-breaker', 40, 5);
report('breaker-fastfail', 40, 0.001);
